1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.model.Region;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
26	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
27	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
31	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "locality", expression = "java(locality(owner))")
33	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
34	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    @Mapping(target = "bulkSignupWarning", ignore = true)
37	    @Mapping(target = "capacityWarning", ignore = true)
38	    @Mapping(target = "identityKey", ignore = true)
39	    @Mapping(target = "possibleDuplicate", ignore = true)
40	    @Mapping(target = "possibleDuplicateOf", ignore = true)
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * Derives the owner's {@code selfLink}: the canonical link to the owner, formatted
45	     * {@code '/api/owners/' + id}. Returns {@code null} when the owner has no id (e.g. an
46	     * unpersisted owner), in which case the field is absent from the response.
47	     *
48	     * @param owner the owner being mapped
49	     * @return the owner's self link, or {@code null} when the owner has no id
50	     */
51	    default String selfLink(Owner owner) {
52	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
53	    }
54	
55	    /**
56	     * Derives the owner's {@code salutation} from its optional {@code title} and its {@code lastName}:
57	     * the title, a single space and the last name when a title is present (e.g. {@code 'DR Franklin'}),
58	     * otherwise just the last name. A {@code null} or blank title yields the bare last name.
59	     *
60	     * @param owner the owner being mapped
61	     * @return the derived salutation
62	     */
63	    default String salutation(Owner owner) {
64	        String title = owner.getTitle();
65	        if (title == null || title.isBlank()) {
66	            return owner.getLastName();
67	        }
68	        return title + " " + owner.getLastName();
69	    }
70	
71	    /**
72	     * Derives the owner's {@code contactPreference} from the owner's own fields:
73	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
74	     *
75	     * @param owner the owner being mapped
76	     * @return the derived contact preference
77	     */
78	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
79	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
80	    }
81	
82	    /**
83	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
84	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
85	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
86	     * rather than repeated at each use.
87	     *
88	     * @param owner the owner being mapped
89	     * @return {@code true} when the owner has a non-blank email
90	     */
91	    default boolean hasEmail(Owner owner) {
92	        return owner.getEmail() != null && !owner.getEmail().isBlank();
93	    }
94	
95	    /**
96	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
97	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
98	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
99	     * case the field is absent from the response. The age in whole years is the number of complete
100	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
101	     * registration date is somehow absent the current date is used as the reference.
102	     *
103	     * @param owner the owner being mapped
104	     * @return the derived age band, or {@code null} when no birth date is present
105	     */
106	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
107	        java.time.LocalDate birthDate = owner.getBirthDate();
108	        if (birthDate == null) {
109	            return null;
110	        }
111	        java.time.LocalDate reference = owner.getRegistrationDate() != null
112	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
113	        int age = java.time.Period.between(birthDate, reference).getYears();
114	        if (age < 18) {
115	            return OwnerDto.AgeBandEnum.MINOR;
116	        }
117	        if (age < 65) {
118	            return OwnerDto.AgeBandEnum.ADULT;
119	        }
120	        return OwnerDto.AgeBandEnum.SENIOR;
121	    }
122	
123	    /**
124	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
125	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
126	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
127	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
128	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
129	     * identity keeps the locality consistent with the code an owner is issued.
130	     *
131	     * @param owner the owner being mapped
132	     * @return the derived locality
133	     */
134	    default String locality(Owner owner) {
135	        String code = owner.getCustomerCode();
136	        if (code == null) {
137	            return Region.code(owner.getPostcode(), owner.getCity());
138	        }
139	        int dash = code.indexOf('-');
140	        return dash >= 0 ? code.substring(0, dash) : code;
141	    }
142	
143	    /**
144	     * Derives the owner's {@code timezone} as the IANA name for its {@link #locality(Owner) locality}
145	     * region, resolved through the shared fixed region-to-timezone table
146	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
147	     * {@code QLD -> Australia/Brisbane}) in {@link Region#timezoneForCode(String)}. Deriving it from
148	     * the same locality keeps the timezone consistent with the region the owner is labelled with.
149	     * Returns {@code null} when the locality has no known timezone (such as an {@code UNKNOWN}
150	     * region), in which case the field is absent from the response.
151	     *
152	     * @param owner the owner being mapped
153	     * @return the derived IANA timezone name, or {@code null} when the region has no known timezone
154	     */
155	    default String timezone(Owner owner) {
156	        return Region.timezoneForCode(locality(owner));
157	    }
158	
159	    /**
160	     * Derives the owner's {@code membershipPoints} from the owner's factors. Starts at {@code 0},
161	     * adds {@code 2} when an email is present, adds {@code 1} when the owner's {@code namesakeCount}
162	     * is {@code 0}, adds {@code 2} for a household of {@code 3} or more (see
163	     * {@link Owner#getHouseholdSize()}), and adds {@code 3} when the owner's tenure &mdash; the number
164	     * of elapsed fiscal years between its {@code registrationDate} and the current date &mdash; exceeds
165	     * one fiscal year (see {@link #tenureFiscalYears(Owner)}).
166	     *
167	     * @param owner the owner being mapped
168	     * @return the derived membership points
169	     */
170	    default Integer membershipPoints(Owner owner) {
171	        int points = 0;
172	        if (hasEmail(owner)) {
173	            points += 2;
174	        }
175	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
176	        if (uniqueName) {
177	            points += 1;
178	        }
179	        if (owner.getHouseholdSize() >= 3) {
180	            points += 2;
181	        }
182	        if (tenureFiscalYears(owner) > 1) {
183	            points += 3;
184	        }
185	        return points;
186	    }
187	
188	    /**
189	     * Maps the owner's {@code membershipPoints} to its numeric {@code membershipLevel}: level
190	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
191	     * {@code 4} for {@code 6} or more points.
192	     *
193	     * @param owner the owner being mapped
194	     * @return the derived membership level, between {@code 1} and {@code 4}
195	     */
196	    default Integer membershipLevel(Owner owner) {
197	        int points = membershipPoints(owner);
198	        if (points <= 1) {
199	            return 1;
200	        }
201	        if (points <= 3) {
202	            return 2;
203	        }
204	        if (points <= 5) {
205	            return 3;
206	        }
207	        return 4;
208	    }
209	
210	    /**
211	     * Computes the owner's tenure as the number of elapsed fiscal years between the owner's
212	     * {@code registrationDate} and the current date: the fiscal year of "now" minus the fiscal year
213	     * of the registration date (see {@link #fiscalYearNumber(java.time.LocalDate)}). An owner
214	     * registered and read within the same fiscal year has a tenure of {@code 0}; each subsequent
215	     * fiscal year that has started adds one. Returns {@code 0} when no registration date is present,
216	     * so an owner without a registration date has no tenure.
217	     *
218	     * @param owner the owner being mapped
219	     * @return the owner's tenure in elapsed fiscal years, or {@code 0} when no registration date is present
220	     */
221	    default long tenureFiscalYears(Owner owner) {
222	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
223	        if (registrationDate == null) {
224	            return 0;
225	        }
226	        return (long) fiscalYearNumber(java.time.LocalDate.now()) - fiscalYearNumber(registrationDate);
227	    }
228	
229	    /**
230	     * Computes the calendar year that identifies the fiscal year containing {@code date}. The fiscal
231	     * year starts on 1 July and is labelled by the calendar year in which it starts, so a date on or
232	     * after 1 July belongs to that same year's fiscal year, while a date before 1 July belongs to the
233	     * previous year's fiscal year (e.g. {@code 2026-09-06} yields {@code 2026} and {@code 2026-06-15}
234	     * yields {@code 2025}).
235	     *
236	     * @param date the date whose fiscal year is wanted
237	     * @return the calendar year the fiscal year starts in
238	     */
239	    default int fiscalYearNumber(java.time.LocalDate date) {
240	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() : date.getYear() - 1;
241	    }
242	
243	    /**
244	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, where {@code YY} is the last
245	     * two digits of the fiscal year of the (business-day-adjusted) {@code registrationDate} (e.g.
246	     * {@code 'FY26'}). Returns {@code null} when no registration date is present.
247	     *
248	     * @param owner the owner being mapped
249	     * @return the formatted fiscal year, or {@code null} when no registration date is present
250	     */
251	    default String fiscalYear(Owner owner) {
252	        if (owner.getRegistrationDate() == null) {
253	            return null;
254	        }
255	        return String.format("FY%02d", fiscalYearNumber(owner.getRegistrationDate()) % 100);
256	    }
257	
258	    /**
259	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
260	     * where {@code YY} is the last two digits of the fiscal year of the (business-day-adjusted)
261	     * {@code registrationDate} (e.g. {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the
262	     * customer code or the registration date is absent.
263	     *
264	     * @param owner the owner being mapped
265	     * @return the formatted membership number, or {@code null} when it cannot be derived
266	     */
267	    default String membershipNumber(Owner owner) {
268	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
269	            return null;
270	        }
271	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearNumber(owner.getRegistrationDate()) % 100);
272	    }
273	
274	    /**
275	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
276	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
277	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
278	     * the customer code is absent.
279	     *
280	     * @param owner the owner being mapped
281	     * @return the Luhn check digit, or {@code null} when no customer code is present
282	     */
283	    default Integer checkDigit(Owner owner) {
284	        String code = owner.getCustomerCode();
285	        if (code == null) {
286	            return null;
287	        }
288	        int sum = 0;
289	        boolean dbl = true;
290	        for (int i = code.length() - 1; i >= 0; i--) {
291	            char c = code.charAt(i);
292	            if (c < '0' || c > '9') {
293	                continue;
294	            }
295	            int d = c - '0';
296	            if (dbl) {
297	                d *= 2;
298	                if (d > 9) {
299	                    d -= 9;
300	                }
301	            }
302	            sum += d;
303	            dbl = !dbl;
304	        }
305	        return (10 - (sum % 10)) % 10;
306	    }
307	
308	    /**
309	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
310	     * code, a space, then the national-significant digits grouped in threes separated by spaces
311	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
312	     * field keeps the unformatted E.164 value. The split between the country code and the national
313	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
314	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
315	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
316	     * {@code null}, blank, or not in E.164 form.
317	     *
318	     * @param owner the owner being mapped
319	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
320	     */
321	    default String telephoneDisplay(Owner owner) {
322	        String telephone = owner.getTelephone();
323	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
324	            return telephone;
325	        }
326	        String digits = telephone.substring(1);
327	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
328	        String countryCode = digits.substring(0, codeLength);
329	        String national = digits.substring(codeLength);
330	        StringBuilder grouped = new StringBuilder();
331	        for (int i = 0; i < national.length(); i++) {
332	            if (i > 0 && i % 3 == 0) {
333	                grouped.append(' ');
334	            }
335	            grouped.append(national.charAt(i));
336	        }
337	        return "+" + countryCode + " " + grouped;
338	    }
339	
340	    Owner toOwner(OwnerDto ownerDto);
341	
342	    @Mapping(target = "id", ignore = true)
343	    @Mapping(target = "pets", ignore = true)
344	    Owner toOwner(OwnerFieldsDto ownerDto);
345	
346	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
347	
348	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
349	
350	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
351	        OwnerPageDto ownerPageDto = new OwnerPageDto();
352	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
353	        ownerPageDto.setPage(ownerPage.getNumber());
354	        ownerPageDto.setSize(ownerPage.getSize());
355	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
356	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
357	        return ownerPageDto;
358	    }
359	}
