190	    /**
191	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when no
192	     * request is bound or the header is absent. Held in one place so the create endpoint can decide,
193	     * from the key alone, whether a create is a first occurrence or a repeat to be served from the
194	     * originally created owner.
195	     *
196	     * @return the request's idempotency key, or {@code null} when none was supplied
197	     */
198	    private String currentIdempotencyKey() {
199	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
200	            return attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
201	        }
202	        return null;
203	    }
