205	    /**
206	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
207	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
208	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
209	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
210	     * then respond" and the persisted owner is available to callers that need it beyond the response.
211	     *
212	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
213	     * @return the persisted owner, with its derived fields populated
214	     */
215	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
216	        normalizeAddress(ownerFieldsDto);
217	        rejectBlankOwnerFields(ownerFieldsDto);
218	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
219	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
220	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
221	        rejectCityAtCapacity(ownerFieldsDto.getCity());
222	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
223	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
224	        rejectDailyRegistrationLimit(registrationDate);
225	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
226	        ownerFieldsDto.setTelephone(normalizedTelephone);
227	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
228	        ownerFieldsDto.setEmail(normalizedEmail);
229	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
230	        owner.setRegistrationDate(registrationDate);
231	        owner.setCustomerCode(customerCode(owner));
232	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
233	        owner.setHouseholdId(householdId(owner));
234	        rejectDuplicateIdentity(owner);
235	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
236	        this.clinicService.saveOwner(owner);
237	        owner.setHouseholdSize(householdSize(owner));
238	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
239	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
240	            membershipLevel(owner), ownerMapper.membershipNumber(owner));
241	        emitOwnerCreatedEvent(owner);
242	        return owner;
243	    }
