400	    /**
401	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
402	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} and
403	     * {@code capacityWarning} flags, the {@code identityKey} and the {@code possibleDuplicate} pair),
404	     * and re-applies the owner's
405	     * {@code membershipLevel} through the controller ({@link #membershipLevel(Owner)}). Both the
406	     * create endpoint and the single-owner read endpoint return their owner through this method, so
407	     * an owner is decorated identically on either path and each derived field is computed in exactly
408	     * one place.
409	     *
410	     * @param owner the persisted owner to represent
411	     * @return the owner DTO with its derived read-only fields populated
412	     */
413	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
414	        owner.setHouseholdSize(householdSize(owner));
415	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
416	        ownerDto.setMembershipLevel(membershipLevel(owner));
417	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
418	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
419	        ownerDto.setIdentityKey(identityKey(owner));
420	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
421	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
422	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
423	        return ownerDto;
424	    }
