426	    /**
427	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
428	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
429	     * routed through the controller so the create audit log and the single-owner response agree on one
430	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
431	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
432	     *
433	     * <p>Household ceiling: the reported level is capped at one above the current maximum
434	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
435	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
436	     * than the owner itself). With no existing household member no cap applies and the owner-local level
437	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
438	     * capped level), so it depends only on the members' own points and cannot recurse.
439	     *
440	     * @param owner the owner whose reported membership level is wanted
441	     * @return the owner's membership level, capped at one above its household maximum
442	     */
443	    private Integer membershipLevel(Owner owner) {
444	        int ownLevel = ownerMapper.membershipLevel(owner);
445	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
446	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
447	            .mapToInt(this::householdMemberLevel)
448	            .max();
449	        if (maxHouseholdLevel.isEmpty()) {
450	            return ownLevel;
451	        }
452	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
453	    }
454	
455	    /**
456	     * The owner-local membership level of a household member, used only as an input to the household
457	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
458	     * household size} is set from its household before the level is derived, so the member's household
459	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
460	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
461	     *
462	     * @param member an existing member of an owner's household
463	     * @return the member's owner-local membership level
464	     */
465	    private int householdMemberLevel(Owner member) {
466	        member.setHouseholdSize(householdSize(member));
467	        return ownerMapper.membershipLevel(member);
468	    }
