470	    /**
471	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
472	     * every later step - the required-field check, the persisted value and the response - sees the
473	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
474	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
475	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
476	     * steps that read the address.
477	     *
478	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
479	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
480	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
481	     * are preferred when present: the flat {@code address} returned is composed as the normalized
482	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
483	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
484	     * {@code address} retain its own normalized value.
485	     *
486	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
487	     */
488	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
489	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
490	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
491	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
492	        ownerFieldsDto.setAddressLine1(addressLine1);
493	        ownerFieldsDto.setAddressLine2(addressLine2);
494	        if (addressLine1 != null && !addressLine1.isBlank()) {
495	            String composed = addressLine2 != null && !addressLine2.isBlank()
496	                ? addressLine1 + " " + addressLine2
497	                : addressLine1;
498	            ownerFieldsDto.setAddress(composed);
499	        } else {
500	            ownerFieldsDto.setAddress(flatAddress);
501	        }
502	    }
