504	    /**
505	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
506	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
507	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
508	     * blank (e.g. {@code "   "}). The offending field names are reported through an
509	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
510	     * as a 400 response carrying an {@code errors} array of field names.
511	     *
512	     * @param ownerFieldsDto the submitted owner fields
513	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
514	     */
515	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
516	        List<String> blankFields = new ArrayList<>();
517	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
518	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
519	        addRequiredAddress(blankFields, ownerFieldsDto);
520	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
521	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
522	        if (!blankFields.isEmpty()) {
523	            throw new InvalidOwnerFieldsException(blankFields);
524	        }
525	    }
526	
527	    private void addIfBlank(List<String> blankFields, String field, String value) {
528	        if (value != null && value.isBlank()) {
529	            blankFields.add(field);
530	        }
531	    }
532	
533	    /**
534	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
535	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
536	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
537	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
538	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
539	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
540	     *
541	     * @param blankFields the accumulating list of blank required-field names
542	     * @param ownerFieldsDto the submitted owner fields
543	     */
544	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
545	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
546	            blankFields.add("address");
547	        }
548	    }
549	
550	    private boolean isBlank(String value) {
551	        return value == null || value.isBlank();
552	    }
