554	    /**
555	     * Rejects an owner whose {@code email} domain is on the disposable-domain blocklist
556	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is validated
557	     * only when present, so an owner created without one is accepted unchanged; syntactic validity is
558	     * already enforced by Bean Validation's {@code @Email} constraint on {@link OwnerFieldsDto}, so
559	     * this only rejects an otherwise well-formed address that uses a throwaway provider (see
560	     * {@link DisposableEmailDomains#isDisposable(String)} for the case-insensitive domain match). A
561	     * blocklisted address is reported through a {@link DisposableEmailDomainException}, which the
562	     * {@code ExceptionControllerAdvice} renders as a 400 response naming the {@code email} field.
563	     *
564	     * @param email the supplied email, or {@code null} when omitted
565	     * @throws DisposableEmailDomainException if the email's domain is blocklisted
566	     */
567	    private void rejectDisposableEmailDomain(String email) {
568	        if (disposableEmailDomains.isDisposable(email)) {
569	            throw new DisposableEmailDomainException(email);
570	        }
571	    }
