573	    /**
574	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
575	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
576	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
577	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
578	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
579	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
580	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
581	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
582	     *
583	     * @param city the city of the owner being created
584	     * @param postcode the supplied postcode, or {@code null} when omitted
585	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
586	     */
587	    private void rejectInvalidPostcode(String city, String postcode) {
588	        if (postcode == null || postcode.isBlank()) {
589	            return;
590	        }
591	        Region.forCity(city).ifPresent(region -> {
592	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
593	                throw new InvalidOwnerPostcodeException(postcode, city);
594	            }
595	        });
596	    }
