604	    /**
605	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
606	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
607	     * its {@code postcode} (falling back to its {@code city}) through the shared
608	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
609	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
610	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
611	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
612	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
613	     * distinct customer codes.
614	     *
615	     * @param owner the owner being created, with its telephone already normalized
616	     * @return the formatted, de-duplicated customer code
617	     */
618	    private String customerCode(Owner owner) {
619	        String region = Region.code(owner.getPostcode(), owner.getCity());
620	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
621	        String base = region + "-" + hash8;
622	        return deduplicateCustomerCode(base);
623	    }
624	
625	    /**
626	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
627	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
628	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
629	     * held by no existing owner.
630	     *
631	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
632	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
633	     */
634	    private String deduplicateCustomerCode(String base) {
635	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
636	            .map(Owner::getCustomerCode)
637	            .filter(java.util.Objects::nonNull)
638	            .collect(java.util.stream.Collectors.toSet());
639	        if (!existing.contains(base)) {
640	            return base;
641	        }
642	        int n = 2;
643	        while (existing.contains(base + "-" + n)) {
644	            n++;
645	        }
646	        return base + "-" + n;
647	    }
648	
649	    /**
650	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
651	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
652	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
653	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
654	     * new owner and surfaced as the read-only {@code namesakeCount} field.
655	     *
656	     * @param firstName the first name of the owner being created
657	     * @param lastName the last name of the owner being created
658	     * @return the number of existing owners with the same first and last name (case-insensitive)
659	     */
660	    private int namesakeCount(String firstName, String lastName) {
661	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
662	            && equalsIgnoreCase(owner.getLastName(), lastName));
663	    }
664	
665	    private boolean equalsIgnoreCase(String a, String b) {
666	        return a == null ? b == null : a.equalsIgnoreCase(b);
667	    }
668	
669	    /**
670	     * The maximum number of owners a single city may contain. Once a city already holds this many
671	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
672	     */
673	    private static final long MAX_OWNERS_PER_CITY = 50L;
674	
675	    /**
676	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
677	     * owners. Existing owners are matched to the requested city case-insensitively (using
678	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
679	     * the per-city counting used for the customer code. A city at capacity is reported through an
680	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
681	     * 409 Conflict response.
682	     *
683	     * @param city the city of the owner being created
684	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
685	     */
686	    private void rejectCityAtCapacity(String city) {
687	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
688	            throw new OwnerCityAtCapacityException(city);
689	        }
690	    }
691	
692	    /**
693	     * The soft per-city threshold at or above which the read-only {@code capacityWarning} flag is
694	     * raised. Once a city already holds this many owners (but fewer than the hard
695	     * {@link #MAX_OWNERS_PER_CITY} cap), it is flagged as approaching capacity - a warning well
696	     * below the hard rejection at {@link #MAX_OWNERS_PER_CITY}.
697	     */
698	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;
699	
700	    /**
701	     * Derives the read-only {@code capacityWarning} flag for an owner: {@code true} when the owner's
702	     * city already holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and
703	     * {@link #MAX_OWNERS_PER_CITY} minus one owners (40 to 49, approaching the hard per-city capacity
704	     * limit of {@link #MAX_OWNERS_PER_CITY}), otherwise {@code false}. Uses the same per-city
705	     * accumulation as the hard capacity check ({@link #rejectCityAtCapacity(String)}), so the warning
706	     * band sits directly below the rejection at {@link #MAX_OWNERS_PER_CITY}.
707	     *
708	     * @param city the owner's city
709	     * @return {@code true} if the city is approaching, but has not reached, its owner capacity
710	     */
711	    private boolean capacityWarning(String city) {
712	        long owners = ownersInCity(city);
713	        return owners >= CITY_CAPACITY_WARNING_THRESHOLD && owners < MAX_OWNERS_PER_CITY;
714	    }
715	
716	    /**
717	     * Counts the existing owners whose {@code city} matches the given city, compared
718	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
719	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
720	     *
721	     * @param city the city to count owners for
722	     * @return the number of existing owners in that city
723	     */
724	    private long ownersInCity(String city) {
725	        return countOwners(owner -> equalsIgnoreCase(owner.getCity(), city));
726	    }
727	
728	    /**
729	     * The maximum number of owners that may be registered on a single day. Once this many owners
730	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
731	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
732	     */
733	    private static final long MAX_OWNERS_PER_DAY = 100L;
734	
735	    /**
736	     * Resolves the effective registration date for a create request: the value supplied in the
737	     * request when present, otherwise the server's current date. The result is the raw effective
738	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
739	     *
740	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
741	     * @return the supplied date, or today when none was supplied
742	     */
743	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
744	        return suppliedDate != null ? suppliedDate : LocalDate.now();
745	    }
746	
747	    /**
748	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
749	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
750	     * today when omitted - but it may never be in the future. The check is applied to the raw
751	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
752	     * future date is rejected regardless of how that adjustment would move it. A future date is
753	     * reported through a {@link FutureRegistrationDateException}, which the
754	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
755	     * {@code registrationDate} field.
756	     *
757	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
758	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
759	     */
760	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
761	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
762	            throw new FutureRegistrationDateException(suppliedDate);
763	        }
764	    }
765	
766	    /**
767	     * The fixed list of public holidays that are not business days. A registration date that lands
768	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
769	     * business day, exactly as it is rolled forward off a weekend.
770	     */
771	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
772	        LocalDate.of(2026, 1, 1),
773	        LocalDate.of(2026, 1, 26),
774	        LocalDate.of(2026, 4, 25),
775	        LocalDate.of(2026, 12, 25),
776	        LocalDate.of(2026, 12, 28));
777	
778	    /**
779	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
780	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
781	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
782	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
783	     * value - whether supplied in the request or defaulted to the server date - is stored as the
784	     * next business day, and every value derived from the registration date (such as the membership
785	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
786	     *
787	     * @param date the effective registration date
788	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
789	     */
790	    private LocalDate businessDay(LocalDate date) {
791	        while (isNonBusinessDay(date)) {
792	            date = date.plusDays(1);
793	        }
794	        return date;
795	    }
796	
797	    /**
798	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
799	     *
800	     * @param date the date to test
801	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
802	     */
803	    private boolean isNonBusinessDay(LocalDate date) {
804	        DayOfWeek dayOfWeek = date.getDayOfWeek();
805	        return dayOfWeek == DayOfWeek.SATURDAY
806	            || dayOfWeek == DayOfWeek.SUNDAY
807	            || PUBLIC_HOLIDAYS.contains(date);
808	    }
809	
810	    /**
811	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
812	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
813	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
814	     * renders as a 429 Too Many Requests response.
815	     *
816	     * @param date the registration date of the owner being created (today)
817	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
818	     */
819	    private void rejectDailyRegistrationLimit(LocalDate date) {
820	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
821	            throw new DailyOwnerRegistrationLimitException(date);
822	        }
823	    }
824	
825	    /**
826	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
827	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
828	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
829	     * day's owners identically.
830	     *
831	     * @param date the registration date to count owners for
832	     * @return the number of existing owners registered on that day
833	     */
834	    private long ownersRegisteredOn(LocalDate date) {
835	        return countOwners(owner -> date.equals(owner.getRegistrationDate()));
836	    }
837	
838	    /**
839	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
840	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
841	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
842	     */
843	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
844	
845	    /**
846	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
847	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
848	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
849	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
850	     * without a registration date, such as seed data) is never flagged.
851	     *
852	     * @param date the owner's registration date (the day it was created), or {@code null}
853	     * @return {@code true} if the day already holds more than the warning threshold of owners
854	     */
855	    private boolean bulkSignupWarning(LocalDate date) {
856	        if (date == null) {
857	            return false;
858	        }
859	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
860	    }
861	
862	    /**
863	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
864	     * The identity key is the SHA-256 hex digest over
865	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
866	     * {@link #identityKey(Owner)}) and is the single duplicate check: it subsumes the former separate
867	     * telephone, email and household duplicate blocks. Because the telephone is part of the key, two
868	     * owners with the same last name and postcode but <em>different</em> telephones have different
869	     * identity keys and are both allowed (the second is surfaced instead as a soft
870	     * {@code possibleDuplicate}, see {@link #possibleDuplicateOf(Owner)}); only an exact full-key match
871	     * is a duplicate. Owners flagged deleted are ignored (see {@link #findExistingOwner(Function, String)}),
872	     * and the email-domain blocklist has already been applied earlier in the create flow. A collision is
873	     * reported through a {@link DuplicateOwnerIdentityException}, which the {@code ExceptionControllerAdvice}
874	     * renders as a 409 Conflict response.
875	     *
876	     * @param owner the fully-populated owner being created (telephone normalized, email set)
877	     * @throws DuplicateOwnerIdentityException if an existing (non-deleted) owner has the same identity key
878	     */
879	    private void rejectDuplicateIdentity(Owner owner) {
880	        String key = identityKey(owner);
881	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
882	        if (duplicate) {
883	            throw new DuplicateOwnerIdentityException(key);
884	        }
885	    }
886	
887	    /**
888	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
889	     * first existing owner whose {@code identityKey} <em>differs</em> from this owner's yet whose
890	     * {@code lastName} has the same {@linkplain Soundex#encode(String) Soundex code} and whose
891	     * {@code postcode} is equal, or {@code null} when no such owner exists. Because the telephone is
892	     * part of the identity key, an existing owner sharing this owner's last-name sound and postcode but
893	     * carrying a different telephone has a different identity key: it is not a hard duplicate (it passed
894	     * {@link #rejectDuplicateIdentity(Owner)}) and is surfaced here as a soft match instead. An existing
895	     * owner with the <em>same</em> identity key would already have been rejected as a 409 and so is
896	     * excluded by the differing-key condition. A blank {@code postcode} never matches, since two owners
897	     * without a postcode do not share one. The captured id is stored on the new owner and surfaced as
898	     * the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
899	     *
900	     * @param owner the fully-populated owner being created (telephone normalized)
901	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
902	     */
903	    private Integer possibleDuplicateOf(Owner owner) {
904	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
905	            return null;
906	        }
907	        String key = identityKey(owner);
908	        String lastNameSoundex = soundex.encode(owner.getLastName());
909	        return this.clinicService.findAllOwners().stream()
910	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode())
911	                && lastNameSoundex.equals(soundex.encode(existing.getLastName()))
912	                && !key.equals(identityKey(existing)))
913	            .map(Owner::getId)
914	            .filter(java.util.Objects::nonNull)
915	            .findFirst()
916	            .orElse(null);
917	    }
918	
919	    /**
920	     * Reduces an owner to its derived {@code identityKey}: the full lower-case SHA-256 hex digest (see
921	     * {@link Sha256Hasher#hex(String)}) over {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} -
922	     * the owner's telephone reduced to its canonical E.164 form (see
923	     * {@link TelephoneNormalizer#canonicalize(String)}), the owner's normalized (lower-cased) email or
924	     * the empty string when absent (see {@link EmailNormalizer#normalize(String)}), and the
925	     * {@linkplain Soundex#encode(String) Soundex code} of the owner's last name, joined by {@code '|'}.
926	     * Two owners are duplicates exactly when their whole identity keys are equal. The hashed input never
927	     * contains {@code null} segments, so the create endpoint's single duplicate check compares this one
928	     * value across owners.
929	     *
930	     * @param owner the owner to derive the identity key for
931	     * @return the owner's identity key, a 64-character lower-case hex string
932	     */
933	    private String identityKey(Owner owner) {
934	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
935	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
936	        String email = normalizedEmail == null ? "" : normalizedEmail;
937	        String lastNameSoundex = soundex.encode(owner.getLastName());
938	        return sha256Hasher.hex(telephone + "|" + email + "|" + lastNameSoundex);
939	    }
940	
941	    /**
942	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
943	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
944	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
945	     * checks reduce both an existing owner and the owner being created to the same canonical key;
946	     * this returns the matched existing owner itself, so a caller can either reject the collision or
947	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
948	     * collision with only a deleted owner is not reported and the create is allowed.
949	     *
950	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
951	     * @param key the canonical key of the owner being created
952	     * @return the first existing owner sharing the key, or empty when none does
953	     */
954	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
955	        return this.clinicService.findAllOwners().stream()
956	            .filter(owner -> !owner.isDeleted())
957	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
958	            .findFirst();
959	    }
960	
961	    /**
962	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
963	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
964	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
965	     * being created to the same canonical key and reject a match.
966	     *
967	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
968	     * @param key the canonical key of the owner being created
969	     * @return {@code true} if some existing owner shares the key
970	     */
971	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
972	        return findExistingOwner(keyExtractor, key).isPresent();
973	    }
974	
975	    /**
976	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
977	     * count-based rules - the per-city capacity, the per-day create limit and the derived
978	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
979	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
980	     * place and each rule supplies just its own predicate.
981	     *
982	     * @param predicate the condition an owner must satisfy to be counted
983	     * @return the number of existing owners that satisfy the predicate
984	     */
985	    private long countOwners(Predicate<Owner> predicate) {
986	        return this.clinicService.findAllOwners().stream()
987	            .filter(predicate)
988	            .count();
989	    }
990	
991	    /**
992	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
993	     * shared {@code householdId}.
994	     */
995	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
996	
997	    /**
998	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
999	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
1000	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
1001	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
1002	     *
1003	     * @param value the raw field value, or {@code null}
1004	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
1005	     */
1006	    private String canonicalizeHousehold(String value) {
1007	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
1008	    }
1009	
1010	    /**
1011	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
1012	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
1013	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
1014	     * for the last-name normalization), so every owner with the same last name and postcode -
1015	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
1016	     * a postcode have no household basis and are given no household id ({@code null}).
1017	     *
1018	     * @param owner the owner being created
1019	     * @return the shared household identifier, or {@code null} when the owner has no postcode
1020	     */
1021	    /**
1022	     * Counts the owners in the given owner's household: the existing owners that share its
1023	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
1024	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
1025	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
1026	     * household factor of the owner's membership points.
1027	     *
1028	     * @param owner the owner whose household size is being derived
1029	     * @return the number of owners in the owner's household (at least {@code 1})
1030	     */
1031	    private int householdSize(Owner owner) {
1032	        if (owner.getHouseholdId() == null) {
1033	            return 1;
1034	        }
1035	        return householdMembers(owner).size();
1036	    }
1037	
1038	    /**
1039	     * The existing owners that make up the given owner's household: those sharing its
1040	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
1041	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
1042	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
1043	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
1044	     * counts it among its household, while one taken before the save sees only the owners already
1045	     * present. Holding the household lookup in one place lets every household-derived value read the
1046	     * same set of members.
1047	     *
1048	     * @param owner the owner whose household members are wanted
1049	     * @return the owners sharing the owner's household, or an empty list when it has no household
1050	     */
1051	    private List<Owner> householdMembers(Owner owner) {
1052	        String household = owner.getHouseholdId();
1053	        if (household == null) {
1054	            return List.of();
1055	        }
1056	        return this.clinicService.findAllOwners().stream()
1057	            .filter(existing -> household.equals(existing.getHouseholdId()))
1058	            .toList();
1059	    }
1060	
1061	    private String householdId(Owner owner) {
1062	        String postcode = owner.getPostcode();
1063	        if (postcode == null || postcode.isBlank()) {
1064	            return null;
1065	        }
1066	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
1067	        return sha256Hasher.hexPrefix(key, HOUSEHOLD_ID_LENGTH);
1068	    }
1069	
1070	    /**
1071	     * Number of leading hex characters of the household hash retained as the shared
1072	     * {@code householdId}.
1073	     */
1074	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1075	}
